</section></div>
<script>
(function(){const status=document.getElementById('sigAdminStatus'),search=document.getElementById('sigAdminSearch'),rows=[...document.querySelectorAll('.sig-admin-row')],none=document.getElementById('sigAdminNone');if(!status||!search)return;function filter(){const query=search.value.toLocaleLowerCase('fr').trim();let count=0;rows.forEach(row=>{const visible=(!status.value||row.dataset.status===status.value)&&(!query||row.textContent.toLocaleLowerCase('fr').includes(query));row.hidden=!visible;if(visible)count++;});none.hidden=count>0;}status.addEventListener('change',filter);search.addEventListener('input',filter);})();
</script>
